import { createRequire } from 'node:module';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { describe, it, expect, beforeEach, afterEach } from 'vitest';

const require = createRequire(import.meta.url);
const { openStorage } = require('../../src/main/storage/index.js');
const { startStorage } = require('../../src/main/startup.js');
const { buildTree } = require('../../src/shared/tree-model.js');
const { createCollectionService } = require('../../src/main/collections/service.js');

// Fixture generated by the pre-feature code (see tests/fixtures/v1-store/README.txt).
const FIXTURE = path.join(__dirname, '..', 'fixtures', 'v1-store', 'media-organizer-store.json');
const PLACEHOLDER = '@@ROOT@@';

let work; // realpath of a fresh temp dir; stands in for the fixture's @@ROOT@@
let storeFile;

beforeEach(() => {
  work = fs.realpathSync(fs.mkdtempSync(path.join(os.tmpdir(), 'mo-v1-')));
  storeFile = path.join(work, 'app-data', 'store.json');
});
afterEach(() => {
  fs.rmSync(work, { recursive: true, force: true });
});

// Writes the fixture to storeFile with the placeholder rewritten to `work`.
// The recorded folders do not exist unless `materialize` is true.
function installFixture({ materialize = false } = {}) {
  const text = fs.readFileSync(FIXTURE, 'utf8').split(PLACEHOLDER).join(work);
  fs.mkdirSync(path.dirname(storeFile), { recursive: true });
  fs.writeFileSync(storeFile, text);
  if (materialize) {
    for (const d of ['photos', 'shared', 'videos', 'docs', 'extra']) fs.mkdirSync(path.join(work, d), { recursive: true });
  }
}

const readText = () => fs.readFileSync(storeFile, 'utf8');
const readJson = () => JSON.parse(readText());
const open = () => openStorage({ location: { file: storeFile } });
const serviceFor = (extra = {}) => createCollectionService({ storage: open(), ...extra });
const names = (list) => list.map((c) => c.name).sort();

// Everything the store holds for one collection, serialized: record, folders, index.
function slice(state, collectionId) {
  const folders = Object.values(state.folders).filter((f) => f.collectionId === collectionId);
  return JSON.stringify({
    collection: state.collections[collectionId],
    folders,
    index: folders.map((f) => state.index[f.id]),
  });
}

function expectUntouched(before, after, ids) {
  for (const id of ids) expect(slice(after, id)).toBe(slice(before, id));
}

describe('a v1 store written by the pre-feature code', () => {
  it('has the shape the README lists', () => {
    installFixture();
    const state = readJson();
    expect(state.version).toBe(1);
    expect(Object.keys(state.collections).sort()).toEqual(['c1', 'c2', 'c3']);
    expect(state.collections.c1.folderIds).toEqual(['f1', 'f2']);
    expect(Object.keys(state.folders).sort()).toEqual(['f1', 'f2', 'f3', 'f4', 'f5', 'f6', 'f7']);
    expect(state.folders.f2.path).toBe(state.folders.f3.path);
    expect(state.folders.f6.unavailable).toBe(true);
    expect(Object.values(state.index).flat()).toHaveLength(8);
  });

  it('opens with openStorage and startStorage, same collections, folders and index, without the folders existing', async () => {
    installFixture();
    const storage = open();
    expect(names(storage.listCollections())).toEqual(['Archive', 'Holiday', 'Mixed']);
    expect(storage.listFolders().map((f) => f.id).sort()).toEqual(['f1', 'f2', 'f3', 'f4', 'f5', 'f6', 'f7']);
    expect(storage.getIndex()).toHaveLength(8);
    expect(storage.getIndex({ folderId: 'f1' }).map((f) => f.name).sort()).toEqual(['a.jpg', 'b.png']);
    expect(storage.getFolder('f1').path).toBe(path.join(work, 'photos'));
    expect(storage.getFolder('f6').unavailable).toBe(true);

    const reportError = () => {
      throw new Error('must not report');
    };
    const started = await startStorage({ baseDir: path.dirname(storeFile), openStorage, reportError });
    expect(started.ok).toBe(true);
    expect(started.storage.listCollections()).toEqual(storage.listCollections());
    expect(started.storage.listFolders()).toEqual(storage.listFolders());
    expect(started.storage.getIndex()).toEqual(storage.getIndex());
  });

  it('writes nothing when opened (file bytes and directory unchanged)', async () => {
    installFixture();
    const before = fs.readFileSync(storeFile);
    const listing = fs.readdirSync(path.dirname(storeFile)).sort();
    open();
    await startStorage({ baseDir: path.dirname(storeFile), openStorage, reportError: () => {} });
    expect(fs.readFileSync(storeFile).equals(before)).toBe(true);
    expect(fs.readdirSync(path.dirname(storeFile)).sort()).toEqual(listing);
  });

  it('still lists a folder that folderIds lacks in collectionView', () => {
    installFixture();
    const view = serviceFor().getCollectionView('c1');
    expect(view.collection.folderIds).toEqual(['f1', 'f2']);
    expect(view.folders.map((f) => f.id).sort()).toEqual(['f1', 'f2', 'f7']);
    expect(view.files.map((f) => f.name).sort()).toEqual(['a.jpg', 'b.png', 'e.jpg', 's.jpg']);
    expect(serviceFor().getCollectionView('nope')).toBeNull();
  });

  it('getCollectionView of the unavailable folder marks its files unavailable and writes nothing', () => {
    installFixture();
    const before = readText();
    const view = serviceFor().getCollectionView('c3');
    expect(view.files.find((f) => f.name === 'g.jpg').unavailable).toBe(true);
    expect(view.files.find((f) => f.name === 'd.txt').unavailable).toBeUndefined();
    expect(readText()).toBe(before);
  });

  it('listCollectionSummaries works and keeps version 1 and the flags of folders that still match', async () => {
    installFixture({ materialize: true });
    const before = readJson();
    const summaries = await serviceFor().listCollectionSummaries();
    expect(summaries.map((s) => s.name).sort()).toEqual(['Archive', 'Holiday', 'Mixed']);
    const holiday = summaries.find((s) => s.id === 'c1');
    expect(holiday.folderCount).toBe(3);
    expect(summaries.find((s) => s.id === 'c3').folders.find((f) => f.id === 'f6').unavailable).toBe(true);
    const after = readJson();
    expect(after.version).toBe(1);
    expect(after).toEqual(before); // nothing differed, so nothing changed
  });

  it('renameCollection renames one collection; the others stay byte-identical', async () => {
    installFixture();
    const before = readJson();
    const view = await serviceFor().renameCollection('c2', '  Renamed  ');
    expect(view.collection.name).toBe('Renamed');
    const after = readJson();
    expect(after.version).toBe(1);
    expect(after.collections.c2).toEqual({ ...before.collections.c2, name: 'Renamed' });
    expectUntouched(before, after, ['c1', 'c3']);
    expect(slice({ ...after, collections: before.collections }, 'c2')).toBe(slice(before, 'c2'));
  });

  it('removeFolder removes one folder, including one folderIds lacked; the others stay byte-identical', async () => {
    installFixture();
    const before = readJson();
    const svc = serviceFor();
    const view = await svc.removeFolder('c1', 'f1');
    expect(view.folders.map((f) => f.id).sort()).toEqual(['f2', 'f7']);
    let after = readJson();
    expect(after.version).toBe(1);
    expect(after.collections.c1.folderIds).toEqual(['f2']);
    expect(after.index.f1).toBeUndefined();
    expectUntouched(before, after, ['c2', 'c3']);

    // f7 is a folder record that folderIds never listed; removing it works too.
    const view2 = await svc.removeFolder('c1', 'f7');
    expect(view2.folders.map((f) => f.id)).toEqual(['f2']);
    after = readJson();
    expect(after.version).toBe(1);
    expect(after.folders.f7).toBeUndefined();
    expect(after.collections.c1.folderIds).toEqual(['f2']);
    expectUntouched(before, after, ['c2', 'c3']);
  });

  it('addFolder adds a folder from a temp directory; the others stay byte-identical', async () => {
    installFixture();
    const before = readJson();
    const added = path.join(work, 'added');
    fs.mkdirSync(added);
    fs.writeFileSync(path.join(added, 'n.jpg'), 'n');
    const view = await serviceFor({ idGenerator: () => 'new1' }).addFolder('c3', added);
    expect(view.folders.map((f) => f.id).sort()).toEqual(['f5', 'f6', 'new1']);
    expect(view.files.map((f) => f.name)).toContain('n.jpg');
    const after = readJson();
    expect(after.version).toBe(1);
    expect(after.collections.c3.folderIds).toEqual(['f5', 'f6', 'new1']);
    expectUntouched(before, after, ['c1', 'c2']);
  });

  it('deleteCollection with confirm true deletes one collection; the others stay byte-identical', async () => {
    installFixture();
    const before = readJson();
    const requests = [];
    const confirm = async (request) => {
      requests.push(request);
      return true;
    };
    const result = await serviceFor({ confirm }).deleteCollection('c2');
    expect(result).toEqual({ deleted: true });
    expect(requests).toHaveLength(1);
    const after = readJson();
    expect(after.version).toBe(1);
    expect(after.collections.c2).toBeUndefined();
    expect(after.folders.f3).toBeUndefined();
    expect(after.folders.f4).toBeUndefined();
    expectUntouched(before, after, ['c1', 'c3']);
  });

  it('deleteCollection with a declined confirmation changes nothing', async () => {
    installFixture();
    const before = readText();
    expect(await serviceFor({ confirm: async () => false }).deleteCollection('c2')).toEqual({ canceled: true });
    expect(readText()).toBe(before);
  });

  it('loadCollections returns all three collections', async () => {
    installFixture({ materialize: true });
    const loaded = await serviceFor().loadCollections();
    expect(names(loaded.map((l) => l.collection))).toEqual(['Archive', 'Holiday', 'Mixed']);
    expect(readJson().version).toBe(1);
  });
});

describe('a v1 store written by createCollection in the current code', () => {
  async function build() {
    for (const [rel, text] of [['one/a.jpg', 'a'], ['one/b.png', 'b'], ['two/c.mp4', 'c']]) {
      fs.mkdirSync(path.dirname(path.join(work, rel)), { recursive: true });
      fs.writeFileSync(path.join(work, rel), text);
    }
    const svc = serviceFor();
    await svc.createCollection('First', [path.join(work, 'one'), path.join(work, 'two')]);
    await svc.createCollection('Second', [path.join(work, 'two')]);
  }

  it('opens with openStorage and startStorage, writes nothing, and keeps version 1', async () => {
    await build();
    const before = fs.readFileSync(storeFile);
    const storage = open();
    expect(names(storage.listCollections())).toEqual(['First', 'Second']);
    expect(storage.listFolders()).toHaveLength(3);
    expect(storage.getIndex()).toHaveLength(4);
    const started = await startStorage({ baseDir: path.dirname(storeFile), openStorage, reportError: () => {} });
    expect(started.ok).toBe(true);
    expect(fs.readFileSync(storeFile).equals(before)).toBe(true);
    expect(readJson().version).toBe(1);
    const first = storage.listCollections().find((c) => c.name === 'First');
    expect(serviceFor().getCollectionView(first.id).folders).toHaveLength(2);
  });

  it('works with the operations and keeps the other collection byte-identical', async () => {
    await build();
    const before = readJson();
    const [first, second] = ['First', 'Second'].map((n) => Object.values(before.collections).find((c) => c.name === n));
    const view = await serviceFor().removeFolder(first.id, first.folderIds[0]);
    expect(view.folders).toHaveLength(1);
    const after = readJson();
    expect(after.version).toBe(1);
    expectUntouched(before, after, [second.id]);
  });
});

describe('a store with version 2', () => {
  it('fails to open with unsupported-format and is not modified', async () => {
    fs.mkdirSync(path.dirname(storeFile), { recursive: true });
    const v2 = readJsonFromFixtureWithVersion(2);
    fs.writeFileSync(storeFile, v2);
    const before = fs.readFileSync(storeFile);
    let error;
    try {
      open();
    } catch (e) {
      error = e;
    }
    expect(error.code).toBe('STORE_OPEN_FAILED');
    expect(error.reason).toBe('unsupported-format');
    expect(error.foundVersion).toBe(2);
    const reported = [];
    const started = await startStorage({
      baseDir: path.dirname(storeFile),
      openStorage,
      reportError: (m) => reported.push(m),
    });
    expect(started.ok).toBe(false);
    expect(reported).toHaveLength(1);
    expect(fs.readFileSync(storeFile).equals(before)).toBe(true);
    expect(fs.readdirSync(path.dirname(storeFile))).toEqual(['store.json']);
  });
});

describe('a v1 store holding nested and identical roots', () => {
  const rec = (folderId, root, rel) => ({
    path: path.join(root, rel),
    relativePath: rel,
    name: path.basename(rel),
    extension: 'jpg',
    kind: 'image',
    folderId,
    collectionId: 'c1',
  });

  // Writes collection c1 whose folder records are [{ id, path, files: [relativePath] }].
  // The directories exist; the files are only in the index.
  function writeLegacy(records) {
    const storage = open();
    storage.putCollection({ id: 'c1', name: 'Legacy', folderIds: [], createdAt: '2026-10-20T00:00:00.000Z' });
    for (const r of records) {
      fs.mkdirSync(r.path, { recursive: true });
      storage.putFolder({ id: r.id, collectionId: 'c1', path: r.path, unavailable: false });
      storage.replaceFolderIndex(r.id, r.files.map((rel) => rec(r.id, r.path, rel)));
    }
  }

  const top = () => path.join(work, 'top');
  const nested = () => [
    { id: 'outer', path: path.join(top(), 'outer'), files: ['inner/x.jpg'] },
    { id: 'inner', path: path.join(top(), 'outer', 'inner'), files: ['x.jpg'] },
  ];
  const identical = () => [
    { id: 'first', path: path.join(work, 'same'), files: ['a.jpg'] },
    { id: 'second', path: path.join(work, 'same'), files: ['a.jpg'] },
  ];
  const filesIn = (node) => node.children.flatMap((c) => (c.type === 'file' ? [c] : filesIn(c)));

  it('shows a file once under the outer root and keeps the inner root, without writing', () => {
    writeLegacy(nested());
    const before = fs.readFileSync(storeFile);
    const view = serviceFor().getCollectionView('c1');
    expect(view.collection.folderIds).toEqual(['outer', 'inner']);
    expect(view.folders.map((f) => f.id)).toEqual(['outer', 'inner']);
    const tree = buildTree(view.folders, view.files);
    expect(tree.map((r) => r.folderId).sort()).toEqual(['inner', 'outer']);
    const outer = tree.find((r) => r.folderId === 'outer');
    const inner = tree.find((r) => r.folderId === 'inner');
    expect(filesIn(outer).map((f) => f.path)).toEqual([path.join(top(), 'outer', 'inner', 'x.jpg')]);
    expect(filesIn(inner)).toEqual([]);
    expect(fs.readFileSync(storeFile).equals(before)).toBe(true);
    expect(readJson().version).toBe(1);
  });

  it('gives the file of two identical-path records to the earlier in folderIds', () => {
    writeLegacy(identical());
    const before = fs.readFileSync(storeFile);
    const view = serviceFor().getCollectionView('c1');
    expect(view.folders.map((f) => f.id)).toEqual(['first', 'second']);
    const tree = buildTree(view.folders, view.files);
    expect(tree.map((r) => r.folderId).sort()).toEqual(['first', 'second']);
    expect(filesIn(tree.find((r) => r.folderId === 'first'))).toHaveLength(1);
    expect(filesIn(tree.find((r) => r.folderId === 'second'))).toEqual([]);
    expect(fs.readFileSync(storeFile).equals(before)).toBe(true);
  });

  it('keeps version 1 after renameCollection, removeFolder and deleteCollection', async () => {
    writeLegacy(nested());
    const svc = serviceFor({ confirm: async () => true });
    await svc.renameCollection('c1', 'Renamed');
    expect(readJson().version).toBe(1);
    await svc.removeFolder('c1', 'inner');
    expect(readJson().version).toBe(1);
    expect(readJson().collections.c1.folderIds).toEqual(['outer']);
    expect(await svc.deleteCollection('c1')).toEqual({ deleted: true });
    expect(readJson().version).toBe(1);
    expect(readJson().collections.c1).toBeUndefined();
  });

  it('addFolder of a folder containing both nested folders replaces both and keeps version 1', async () => {
    writeLegacy(nested());
    const requests = [];
    const confirm = async (request) => {
      requests.push(request);
      return true;
    };
    const view = await serviceFor({ confirm, idGenerator: () => 'wide' }).addFolder('c1', top());
    expect(requests).toHaveLength(1);
    expect(view.replaced.slice().sort()).toEqual(nested().map((r) => r.path).sort());
    expect(view.folders.map((f) => f.id)).toEqual(['wide']);
    const after = readJson();
    expect(after.version).toBe(1);
    expect(after.collections.c1.folderIds).toEqual(['wide']);
    expect(after.folders.outer).toBeUndefined();
    expect(after.folders.inner).toBeUndefined();
    expect(after.index.outer).toBeUndefined();
    expect(after.index.inner).toBeUndefined();
  });

  it('addFolder of a folder inside the legacy outer folder is refused with FOLDER_COVERED and writes nothing', async () => {
    writeLegacy(nested());
    const sub = path.join(top(), 'outer', 'sub');
    fs.mkdirSync(sub);
    const before = fs.readFileSync(storeFile);
    const confirm = async () => {
      throw new Error('must not ask');
    };
    await expect(serviceFor({ confirm }).addFolder('c1', sub)).rejects.toMatchObject({ code: 'FOLDER_COVERED' });
    expect(fs.readFileSync(storeFile).equals(before)).toBe(true);
  });
});

function readJsonFromFixtureWithVersion(version) {
  const state = JSON.parse(fs.readFileSync(FIXTURE, 'utf8').split(PLACEHOLDER).join(work));
  return JSON.stringify({ ...state, version });
}
